### 3. Implement observeCharacteristic with notification callback -- `packages/butane_android/android/src/main/kotlin/com/nicospencer/butane_android/ButaneAndroidPlugin.kt`

Replace the observeCharacteristic stub. When `observe=true`, enable notifications and set up a callback that forwards values to Flutter via `flutterApi.onCharacteristicValue()`. When `observe=false`, disable notifications.

Replace `observeCharacteristic()`:

```kotlin
    override fun observeCharacteristic(
        observe: Boolean,
        session: PeripheralSession,
        serviceUuid: String,
        characteristicUuid: String,
        callback: (Result<Unit>) -> Unit,
    ) {
        val connection = connections[session.peripheralIdentifier]
        if (connection == null) {
            callback(Result.failure(FlutterError("not-connected", "Peripheral not connected", null)))
            return
        }
        val characteristic = connection.findCharacteristic(serviceUuid, characteristicUuid)
        if (characteristic == null) {
            callback(Result.failure(FlutterError("not-found", "Characteristic $characteristicUuid not found", null)))
            return
        }
        scope?.launch {
            try {
                if (observe) {
                    connection.notificationCallback = { notifiedChar, value ->
                        val peripheral = Peripheral(
                            session = session,
                            name = null,
                            rssi = null,
                            state = ConnectionState.CONNECTED,
                        )
                        val charObj = Characteristic(
                            uuid = notifiedChar.uuid.toString(),
                            value = value,
                            descriptors = null,
                            properties = null,
                        )
                        flutterApi?.onCharacteristicValue(peripheral, charObj, value) {}
                    }
                    connection.enableNotifications(characteristic)
                } else {
                    connection.disableNotifications(characteristic)
                    connection.notificationCallback = null
                }
                callback(Result.success(Unit))
            } catch (e: Exception) {
                callback(Result.failure(FlutterError("notify-failed", e.message, null)))
            }
        }
    }
