4. Setup helper, step helper, and `round-trip` scenario — append to `nus_suite.dart`

   ```dart
   extension on NusSuite {
     /// Standard setup: add_service, start_advertising, scan, connect,
     /// discover services + characteristics. Captures peripheralId.
     Future<void> _setup(List<StepResult> steps, {bool discover = true}) async {
       steps.add(await _step('add_service', () => peripheral.sendCommand(
         'add_service', params: NusUuids.buildAddServicePayload())));
       steps.add(await _step('start_advertising', () => peripheral.sendCommand(
         'start_advertising', params: {'serviceUuids': [NusUuids.service]})));
       steps.add(await _step('scan', () async {
         final r = await central.sendCommand(
           'scan', params: {'serviceUuids': [NusUuids.service]});
         _peripheralId = ((r['data'] as Map)['peripheral'] as Map)['id'] as String;
         return r;
       }));
       steps.add(await _step('connect', () => central.sendCommand(
         'connect', params: {'peripheralId': _peripheralId})));
       if (discover) {
         steps.add(await _step('discover_services', () => central.sendCommand(
           'discover_services', params: {'peripheralId': _peripheralId})));
         steps.add(await _step('discover_characteristics', () => central.sendCommand(
           'discover_characteristics',
           params: {'peripheralId': _peripheralId, 'serviceUuid': NusUuids.service})));
       }
     }

     Future<StepResult> _step(String name, Future<Map<String, dynamic>> Function() fn) async {
       final sw = Stopwatch()..start();
       try {
         final r = await fn();
         sw.stop();
         final ok = r['success'] as bool? ?? true;
         return StepResult(name: name, success: ok, duration: sw.elapsed,
           error: ok ? null : r['error'] as String?);
       } catch (e) {
         sw.stop();
         return StepResult(name: name, success: false, duration: sw.elapsed, error: e.toString());
       }
     }

     Future<ScenarioResult> _roundTrip() async {
       final sw = Stopwatch()..start();
       final steps = <StepResult>[];
       StreamSubscription<Map<String, dynamic>>? echoSub;
       try {
         await _setup(steps);
         steps.add(await _step('subscribe TX', () => central.sendCommand(
           'subscribe', params: {'peripheralId': _peripheralId,
             'serviceUuid': NusUuids.service, 'characteristicUuid': NusUuids.tx})));

         // Coordinator-driven echo: subscribe to peripheral.events, decode
         // write_request, reply via update_value. (Discovery design option A.)
         echoSub = peripheral.events.listen((event) {
           if (event['event'] != 'write_request') return;
           final data = (event['data'] as Map<String, dynamic>?) ?? event;
           if ((data['characteristicUuid'] as String?)?.toLowerCase()
               != NusUuids.rx.toLowerCase()) return;
           final b64 = data['value'] as String?;
           if (b64 == null) return;
           final decoded = utf8.decode(base64Decode(b64), allowMalformed: true);
           if (decoded != 'PING') return;
           peripheral.sendCommand('update_value', params: {
             'serviceUuid': NusUuids.service,
             'characteristicUuid': NusUuids.tx,
             'value': base64Encode(utf8.encode('PONG')),
           });
         });

         // Listen for PONG BEFORE the PING write.
         final notif = central.events.firstWhere((e) =>
           e['event'] == 'notification' &&
           (e['characteristicUuid'] as String?)?.toLowerCase()
             == NusUuids.tx.toLowerCase()
         ).timeout(const Duration(seconds: 10));

         steps.add(await _step('write PING', () => central.sendCommand(
           'write_characteristic', params: {'peripheralId': _peripheralId,
             'serviceUuid': NusUuids.service, 'characteristicUuid': NusUuids.rx,
             'value': base64Encode(utf8.encode('PING'))})));

         final e = await notif;
         final got = utf8.decode(base64Decode(e['value'] as String));
         if (got != 'PONG') throw StateError('expected PONG, got "$got"');
         sw.stop();
         return ScenarioResult(name: 'round-trip', success: true,
           duration: sw.elapsed, steps: steps,
           diagnostics: {'echo': 'PING->PONG ok'});
       } catch (err) {
         sw.stop();
         return ScenarioResult(name: 'round-trip', success: false,
           duration: sw.elapsed, error: err.toString(), steps: steps);
       } finally {
         await echoSub?.cancel();
       }
     }
   }
   ```

